+        }
+
+        pub(super) fn deserialize_migrator_spec(input: &str) -> MigratorSpec {
+            let (spec, diagnostics) = deserialize_from_json_str::<MigratorSpec>(
+                input,
+                JsonParserOptions::default()
+                    .with_allow_comments()
+                    .with_allow_trailing_commas(),
+                "",
+            )
+            .consume();
+            assert!(
+                diagnostics.is_empty(),
