+            },
+            FlatConfigObject {
+                files: vec![].into(),
+                ignores: vec!["*.spec.js".into()],
+                language_options: None,
+                rules: None,
+            },
+            FlatConfigObject {
+                files: vec!["*.ts".into()].into(),
+                ignores: vec![],
+                language_options: None,
+                rules: Some(Rules(
